sudo -u postgres psql -XAt -F'|' -c "SELECT 'VITO_PRIMARY', s.active, s.wal_status, coalesce(pg_wal_lsn_diff(pg_current_wal_lsn(), s.restart_lsn), 0)::bigint, (SELECT setting FROM pg_settings WHERE name = 'max_slot_wal_keep_size'), coalesce(r.state, ''), coalesce(pg_wal_lsn_diff(pg_current_wal_lsn(), r.replay_lsn)::bigint::text, ''), coalesce((extract(epoch FROM r.write_lag) * 1000)::text, ''), coalesce((extract(epoch FROM r.flush_lag) * 1000)::text, ''), coalesce((extract(epoch FROM r.replay_lag) * 1000)::text, '') FROM pg_replication_slots s LEFT JOIN pg_stat_replication r ON r.pid = s.active_pid WHERE s.slot_name = '{!! $slot !!}'"
